// WF09b - Parse del evento de EvoAPI.
//
// EvoAPI v2 emite eventos con shape:
//   { event: 'GROUP_PARTICIPANTS_UPDATE' | 'group.participants.update' | ...,
//     instance: 'Leon-Test',
//     data: { id: '<jid>', participants: ['<phone>@s.whatsapp.net', ...], action: 'add'|'remove'|... } }
//
// Sólo reaccionamos a action=add (alguien entró al grupo). Si no aplica,
// devolvemos 0 items para parar el flujo limpio.

const body = $input.first().json.body || $input.first().json;
const event = (body.event || '').toLowerCase().replace(/\./g, '_');
const data = body.data || {};
const action = (data.action || '').toLowerCase();

if (event !== 'group_participants_update') return [];
if (action !== 'add') return [];

const groupJid = data.id;
if (!groupJid) return [];

// Lista de phones (sin @s.whatsapp.net) que acaban de entrar
const joinedPhones = (data.participants || []).map(p => String(p).split('@')[0]).filter(Boolean);
if (joinedPhones.length === 0) return [];

return [{ json: { groupJid, joinedPhones, event_at: new Date().toISOString() } }];

// WF09b - Calcula nuevo pending/joined a partir de la row + los phones del evento.
//
// El nodo HTTP Request (Lookup row) hace auto-split de la respuesta array de
// PostgREST: si hay 1 row, $input tiene 1 item; si hay 0 rows, tiene 0 items.
// Si no hay row matching, devolvemos 0 items para parar el flujo limpio.

const items = $input.all();
if (items.length === 0) return [];
const row = items[0]?.json;
if (!row || !row.id) return [];

const ev = $('Parse event').first().json;
const nowIso = ev.event_at;
const justJoined = new Set(ev.joinedPhones);

const oldPending = row.pending_participants || [];
const joinedAt = { ...(row.joined_at || {}) };

for (const phone of justJoined) {
  if (!joinedAt[phone]) joinedAt[phone] = nowIso;
}

const newPending = oldPending.filter(p => !justJoined.has(p.phone));
const allJoinedNow = newPending.length === 0;

return [{
  json: {
    row_id: row.id,
    group_jid: row.group_jid,
    update_pending: newPending,
    update_joined_at: joinedAt,
    all_joined_now: allJoinedNow,
    messages: row.messages || [],
  }
}];

// WF09b - Construye N items con los mensajes SOP guardados en la row para
// que el siguiente nodo Send text los dispare al grupo.

const d = $('Decide next state').first().json;
const messages = d.messages || [];
const groupJid = d.group_jid;

return messages.map((text, i) => ({
  json: { number: groupJid, text, idx: i + 1 }
}));
